<?php

namespace Workbench\App\Filament\Resources\Orders\Schemas;

use Filament\Infolists\Components\ImageEntry;
use Filament\Infolists\Components\TextEntry;
use Filament\Schemas\Components\Flex;
use Filament\Schemas\Schema;
use Filament\Support\Enums\VerticalAlignment;
use Filament\Support\Icons\Heroicon;
use VitisStudio\FilamentHeaderSchema\Components\HeaderSection;
use VitisStudio\FilamentHeaderSchema\Components\Heading;
use VitisStudio\FilamentHeaderSchema\Components\Subheading;
use Workbench\App\Enums\OrderStatus;
use Workbench\App\Models\Order;

/**
 * Generated by `make:filament-header-schema`, then filled in.
 *
 * The trait finds this class by convention, so ListOrders and ViewOrder apply
 * `HasHeaderSchema` and declare nothing else. One class serves both pages,
 * which is why the record-specific parts hide themselves when there is no
 * record to read.
 */
class OrderHeader
{
    public static function configure(Schema $schema): Schema
    {
        return $schema
            ->components([
                HeaderSection::make([
                    // A list page has no record, so the heading falls back to
                    // the page's own title rather than rendering nothing.
                    Heading::make('reference')
                        ->default(fn ($livewire) => $livewire->getHeading()),
                    Flex::make([
                        TextEntry::make('status')->badge()->hiddenLabel()->grow(false),
                        TextEntry::make('placed_at')
                            ->hiddenLabel()
                            ->grow(false)
                            ->date('j M Y')
                            ->icon(Heroicon::OutlinedCalendarDays)
                            ->color('gray'),
                        TextEntry::make('items_count')
                            ->hiddenLabel()
                            ->grow(false)
                            ->formatStateUsing(fn (int $state): string => $state.' items')
                            ->icon(Heroicon::OutlinedShoppingBag)
                            ->color('gray'),
                    ])->visible(fn (?Order $record): bool => filled($record)),
                    Subheading::make('customer.company')
                        ->visible(fn (?Order $record): bool => filled($record)),
                    Subheading::make('summary')
                        ->state(fn (): string => Order::count().' orders, '.Order::where('status', OrderStatus::Pending)->count().' awaiting payment')
                        ->visible(fn (?Order $record): bool => blank($record)),
                ])
                    ->leading(
                        ImageEntry::make('customer.avatar')
                            ->hiddenLabel()
                            ->circular()
                            ->imageSize(64)
                            ->visible(fn (?Order $record): bool => filled($record)),
                        VerticalAlignment::Start,
                    ),
            ]);
    }
}
